Lemma RHEAP_init_proof : forall (m : mem) (auxv : word),
  (forall a : word, 0xeb448 <= bv_unsigned a < 0xeb7f0 -> m a = None) ->      (* [comment removed for export] *)
  (forall a : word, RVMLOCKC <= bv_unsigned a < RVMLOCKC + 4 -> m a = None) ->   (* [comment removed for export] *)
  rw_cells rsegs m 0xeb2d3 [C1 (Z_to_bv 8 0)] ->                              (* [comment removed for export] *)
  rw_cells rsegs m 0xeb2d8 [C8 auxv] ->                                        (* [comment removed for export] *)
  rw_cells rsegs m 0xeb300 [C8 (Z_to_bv 64 4096)] ->                           (* [comment removed for export] *)
  rw_cells rsegs m 0xb82a0 [C8 (Z_to_bv 64 0xeb2b0)] ->                        (* [comment removed for export] *)
  rw_cells rsegs m 0xeb2b0 [C8 (Z_to_bv 64 canary_val)] ->                     (* [comment removed for export] *)
  mem_inv rsegs m ->
  RHEAP (ps_init (reservedZ rsegs)) [] m
